#!/usr/bin/env python3
"""Modernized climate analysis script (Python 3)."""
import configparser
from pathlib import Path

import pandas as pd

BASE_DIR = Path(__file__).resolve().parent / "climate_analyzer"
DATA_FILE = BASE_DIR / "sample_data" / "climate_data.csv"
CONFIG_FILE = BASE_DIR / "config.ini"


def load_config(path: Path) -> configparser.ConfigParser:
    config = configparser.ConfigParser()
    if path.exists():
        config.read(path, encoding="utf-8")
    return config


def load_data(path: Path) -> pd.DataFrame:
    return pd.read_csv(path, encoding="utf-8")


def main() -> None:
    load_config(CONFIG_FILE)
    df = load_data(DATA_FILE)
    for station_id, group in df.groupby("station_id"):
        mean_temp = group["temperature"].mean()
        print(f"Station {station_id} mean temperature: {mean_temp:.1f}°C")


if __name__ == "__main__":
    main()
